## If You Must Keep It Synchronous

```csharp
public class EventProcessor
{
    private readonly ManualResetEventSlim _newEvent = new();
    private readonly Queue<string> _queue = new();
    private Thread? _thread;
    private readonly object _lock = new();
    private CancellationTokenSource? _cts;

    public void Start()
    {
        _cts = new CancellationTokenSource();
        _thread = new Thread(() => RunLoop(_cts.Token));
        _thread.Start();
    }

    private void RunLoop(CancellationToken token)
    {
        try
        {
            while (!token.IsCancellationRequested)
            {
                // Wait for signal OR cancellation
                WaitHandle.WaitAny(new[] { _newEvent.WaitHandle, token.WaitHandle });

                if (token.IsCancellationRequested)
                    break;

                _newEvent.Reset();

                // Drain all items (fixes original race condition)
                while (true)
                {
                    string? item;
                    lock (_lock)
                    {
                        if (_queue.Count == 0) break;
                        item = _queue.Dequeue();
                    }
                    Handle(item);
                }
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts?.Cancel();         // Wakes WaitAny via token.WaitHandle
        _thread?.Join(5000);    // Wait for graceful exit
        _cts?.Dispose();
        _newEvent.Dispose();
    }

    private void Handle(string item) { /* your logic */ }
}
```

